import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Postgres CDC + Outbox App — Quality Report (v1.26-2)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/db/postgres-cdc-outbox-app.md","filePath":"quality-reports/db/postgres-cdc-outbox-app.md"}'),r={name:"quality-reports/db/postgres-cdc-outbox-app.md"};function s(c,e,i,n,p,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="postgres-cdc-outbox-app-—-quality-report-v1-26-2" tabindex="-1">Postgres CDC + Outbox App — Quality Report (v1.26-2) <a class="header-anchor" href="#postgres-cdc-outbox-app-—-quality-report-v1-26-2" aria-label="Permalink to &quot;Postgres CDC + Outbox App — Quality Report (v1.26-2)&quot;">​</a></h1><p>Dogfood: <a href="./../../../examples/dogfood-postgres-cdc-outbox-app/"><code>examples/dogfood-postgres-cdc-outbox-app</code></a>. Package under exercise: <a href="./../../../packages/orm/"><code>@kiwa/orm</code></a> (v0.9).</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The dogfood exercises the 4 Postgres advanced patterns the orm package promises in v0.9:</p><ol><li><strong>Transactional outbox</strong> — Debezium-style outbox row appended in the same transaction as the domain write, LSN monotonic per slot, batch seal preserves order (<code>src/outbox/index.ts</code> wraps <code>@kiwa/orm</code>&#39;s <code>createCdcSession</code> / <code>decodeEvent</code> / <code>appendOutbox</code> / <code>markEventOrdered</code>).</li><li><strong>CDC pickup</strong> — outbox events past a committed LSN are read in order and delivered into a Redis Streams consumer group with at-least-once ack (<code>src/cdc/index.ts</code> + <code>src/consumer/index.ts</code>).</li><li><strong>Streaming replication</strong> — primary write advances LSN, per-replica applied LSN observation, two-step failover (<code>startFailover</code> → <code>promoteReplica</code>) via <code>@kiwa/orm</code>&#39;s replication semantics.</li><li><strong>At-least-once + idempotent consumer</strong> — duplicate LSN ingest is dropped by the consumer seen-set, ack advances the outbox&#39;s <code>confirmedLsn</code>.</li></ol><p>All 4 patterns are driven end-to-end through a provider-neutral adapter (<code>src/adapters/interface.ts</code>) with mock (<code>src/adapters/mock.ts</code>) and real (<code>src/adapters/real.ts</code>) implementations.</p><h2 id="release-gate-—-7-axis-verdict-mock-trace" tabindex="-1">Release gate — 7 axis verdict (mock trace) <a class="header-anchor" href="#release-gate-—-7-axis-verdict-mock-trace" aria-label="Permalink to &quot;Release gate — 7 axis verdict (mock trace)&quot;">​</a></h2><p>Snapshot from <a href="./../../../examples/dogfood-postgres-cdc-outbox-app/quality-report/fidelity-latest"><code>examples/dogfood-postgres-cdc-outbox-app/quality-report/fidelity-latest.md</code></a>.</p><table tabindex="0"><thead><tr><th>axis</th><th>value</th><th>gate</th></tr></thead><tbody><tr><td>coverage — line</td><td>92.00%</td><td>PASS</td></tr><tr><td>coverage — branch</td><td>88.00%</td><td>PASS</td></tr><tr><td>coverage — function</td><td>95.00%</td><td>PASS</td></tr><tr><td>test count — total</td><td>35 (behavior 24 + integration 6 + e2e 5)</td><td>PASS</td></tr><tr><td>fidelity — ratio</td><td>100% mock covered / 0 divergence</td><td>PASS</td></tr><tr><td>perf — p95</td><td>&lt; 2ms per op</td><td>PASS</td></tr><tr><td>mutation — killRate</td><td>73.33% (22/30)</td><td>PASS</td></tr><tr><td><strong>release gate verdict</strong></td><td><strong>PASS</strong></td><td>7 axes evaluated</td></tr></tbody></table><h2 id="real-vs-mock-fidelity" tabindex="-1">Real vs mock fidelity <a class="header-anchor" href="#real-vs-mock-fidelity" aria-label="Permalink to &quot;Real vs mock fidelity&quot;">​</a></h2><p>The 5-op adapter surface reports 5 behavioral divergences under the default <code>POSTGRES_BOOTSTRAP=</code> unset configuration — every real op returns <code>POSTGRES_ENV_MISSING</code> while the mock op succeeds. These are well-defined divergences: the fidelity harness records them without failing the release gate because the real adapter is scope-boxed to aliveness in v1.26-2. A future v1.26-6 publish milestone can extend <code>makeConnectedRealAdapter</code> with an actual <code>pg</code> + wal2json wire once the harness is proved on mock.</p><p>When <code>POSTGRES_BOOTSTRAP</code> is set (e.g. <code>postgres://user:pass@localhost:5432/orders</code>), the adapter runs a DSN aliveness probe and records <code>probe.ok=true</code>, then falls back to <code>REAL_ADAPTER_NOT_IMPLEMENTED</code> for higher-level ops.</p><h2 id="test-map" tabindex="-1">Test map <a class="header-anchor" href="#test-map" aria-label="Permalink to &quot;Test map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>suite</th><th>file</th><th>count</th></tr></thead><tbody><tr><td>outbox invariants</td><td><code>tests/outbox-e2e.spec.ts</code></td><td>6 (T-DPO-001..006)</td></tr><tr><td>replication + failover</td><td><code>tests/replication-lag-e2e.spec.ts</code></td><td>4 (T-DPR-001..004)</td></tr><tr><td>at-least-once + idempotent</td><td><code>tests/at-least-once-e2e.spec.ts</code></td><td>4 (T-DPA-001..004)</td></tr><tr><td>5-op mock E2E</td><td><code>tests/e2e-mock-mode.test.ts</code></td><td>5 (T-DPE-M-001..005)</td></tr><tr><td>fidelity harness</td><td><code>tests/fidelity-report.test.ts</code></td><td>3 (T-DPF-001..003)</td></tr><tr><td>fidelity emit</td><td><code>tests/emit-fidelity-report.test.ts</code></td><td>1 (T-DPE-EM-001)</td></tr><tr><td>real env-gated probe</td><td><code>tests/real-adapter-probe.test.ts</code></td><td>5 (T-DPR-ENV-001..005)</td></tr><tr><td>3-layer perf</td><td><code>tests/perf/dogfood-postgres-cdc-outbox-app.perf.ts</code></td><td>1</td></tr></tbody></table><h2 id="extension-roadmap" tabindex="-1">Extension roadmap <a class="header-anchor" href="#extension-roadmap" aria-label="Permalink to &quot;Extension roadmap&quot;">​</a></h2><ul><li>v1.26-6 publish milestone — extend <code>makeConnectedRealAdapter</code> with a real <code>pg</code> + wal2json client so the fidelity gap closes and behavioural divergences drop below 5.</li><li>follow-up — add testcontainers Postgres 16 harness under a <code>POSTGRES_KEY</code> env-gate so KIWA_MODE=real can spin up a broker in CI without a pre-provisioned instance.</li></ul>',16)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
